modules.server:
var party = require("slopcade/party");
var content = require("slopcade/content");

var ANSWER_TIME_LIMIT = 30;
var VOTE_TIME_LIMIT = 15;
var REVEAL_DURATION_MS = 5000;
var SCORES_DURATION_MS = 5000;
var WINNER_DURATION_MS = 10000;
var DEFAULT_ROUND_COUNT = 3;
var NO_ANSWER = "(no answer)";

function mapToObject(map) {
  var out = {};
  if (!map || typeof map.forEach !== "function") {
    return out;
  }
  map.forEach(function(value, key) {
    out[key] = value;
  });
  return out;
}

function toNumber(value) {
  var n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

exports.run = async function(room, config) {
  await room.setPhase("playing");

  var readyResponses = await room.requestInput("ready-check", {
    type: "buzzer",
    prompt: "Get ready!",
    timeLimit: 5
  });

  var playerIds = [];
  var playerNames = {};

  readyResponses.forEach(function(response, playerId) {
    playerIds.push(playerId);
    playerNames[playerId] = response && response.playerId ? String(response.playerId) : playerId;
  });

  if (playerIds.length < 3) {
    await room.updateSharedData({
      phase: "error",
      errorMessage: "Need at least 3 players"
    });
    await room.setPhase("ended");
    return;
  }

  var scores = {};
  for (var i = 0; i < playerIds.length; i++) {
    scores[playerIds[i]] = 0;
  }

  var roundCount = DEFAULT_ROUND_COUNT;
  if (config && config.roundCount !== undefined) {
    roundCount = toNumber(config.roundCount) || DEFAULT_ROUND_COUNT;
  }

  var pool = Array.isArray(config && config.contentPack) ? config.contentPack : [];
  var shuffledPool = content.shuffle(pool);
  var usedIds = {};

  for (var round = 1; round <= roundCount; round++) {
    var promptsNeeded = playerIds.length;
    var roundPrompts = content.selectForRound(shuffledPool, promptsNeeded, usedIds);

    if (roundPrompts.length < promptsNeeded) {
      usedIds = {};
      shuffledPool = content.shuffle(pool);
      roundPrompts = content.selectForRound(shuffledPool, promptsNeeded, usedIds);
    }

    content.markUsed(usedIds, roundPrompts);

    var matchupDefs = party.createMatchups(playerIds, roundPrompts);
    var assignments = {};

    for (i = 0; i < playerIds.length; i++) {
      assignments[playerIds[i]] = [];
    }

    for (i = 0; i < matchupDefs.length; i++) {
      var definition = matchupDefs[i];
      var promptText = definition.item && definition.item.text ? definition.item.text : "";
      assignments[definition.playerA].push({ matchupIndex: i, promptText: promptText });
      assignments[definition.playerB].push({ matchupIndex: i, promptText: promptText });
    }

    await room.updateSharedData({
      phase: "answering",
      roundNumber: round,
      roundMultiplier: round,
      assignmentsJson: JSON.stringify(assignments),
      timerRemaining: ANSWER_TIME_LIMIT,
      matchupIndex: 0,
      totalMatchups: matchupDefs.length
    });

    var answerResponses = await room.requestInput("answers-r" + round, {
      type: "text",
      prompt: "Submit your answers",
      timeLimit: ANSWER_TIME_LIMIT
    });

    var answersByPlayer = {};
    answerResponses.forEach(function(response, playerId) {
      try {
        answersByPlayer[playerId] = JSON.parse(String(response && response.value ? response.value : "{}"));
      } catch (_error) {
        answersByPlayer[playerId] = {};
      }
    });

    var matchups = [];
    for (i = 0; i < matchupDefs.length; i++) {
      definition = matchupDefs[i];
      promptText = definition.item && definition.item.text ? definition.item.text : "";
      var playerAAnswers = answersByPlayer[definition.playerA] || {};
      var playerBAnswers = answersByPlayer[definition.playerB] || {};

      matchups.push({
        promptText: promptText,
        playerA: definition.playerA,
        playerB: definition.playerB,
        answerA: playerAAnswers[i] || NO_ANSWER,
        answerB: playerBAnswers[i] || NO_ANSWER
      });
    }

    for (var matchupIndex = 0; matchupIndex < matchups.length; matchupIndex++) {
      var matchup = matchups[matchupIndex];
      var voters = playerIds.filter(function(playerId) {
        return playerId !== matchup.playerA && playerId !== matchup.playerB;
      });

      await room.updateSharedData({
        phase: "voting",
        roundNumber: round,
        roundMultiplier: round,
        promptText: matchup.promptText,
        answerA: matchup.answerA,
        answerB: matchup.answerB,
        matchupIndex: matchupIndex + 1,
        totalMatchups: matchups.length,
        timerRemaining: VOTE_TIME_LIMIT,
        votersJson: JSON.stringify(voters)
      });

      var voteResponses = await room.requestInput("vote-r" + round + "-m" + matchupIndex, {
        type: "choice",
        prompt: matchup.promptText,
        options: [matchup.answerA, matchup.answerB],
        timeLimit: VOTE_TIME_LIMIT
      });

      var normalizedVotes = {};
      voteResponses.forEach(function(response, voterId) {
        if (voterId === matchup.playerA || voterId === matchup.playerB) {
          return;
        }

        var value = String(response && response.value !== undefined ? response.value : "");
        if (value === matchup.answerA || value === "0") {
          normalizedVotes[voterId] = { value: "a" };
        } else if (value === matchup.answerB || value === "1") {
          normalizedVotes[voterId] = { value: "b" };
        }
      });

      var voteCounts = party.tallyVotes(normalizedVotes, true, {
        a: matchup.playerA,
        b: matchup.playerB
      });

      var pointsByChoice = party.calculatePoints(voteCounts, {
        basePoints: 1000,
        roundMultiplier: round,
        cleanSweepMultiplier: 1.25
      });

      var votesA = voteCounts.a || 0;
      var votesB = voteCounts.b || 0;
      var totalVotes = votesA + votesB;
      var pointsA = pointsByChoice.a || 0;
      var pointsB = pointsByChoice.b || 0;
      var percentA = totalVotes > 0 ? Math.round((votesA / totalVotes) * 100) : 0;
      var percentB = totalVotes > 0 ? Math.round((votesB / totalVotes) * 100) : 0;

      scores[matchup.playerA] = (scores[matchup.playerA] || 0) + pointsA;
      scores[matchup.playerB] = (scores[matchup.playerB] || 0) + pointsB;

      await room.updatePlayerScore(matchup.playerA, pointsA);
      await room.updatePlayerScore(matchup.playerB, pointsB);

      var scoreboard = party.createScoreboard(scores, playerNames);

      await room.updateSharedData({
        phase: "reveal",
        roundNumber: round,
        roundMultiplier: round,
        promptText: matchup.promptText,
        answerA: matchup.answerA,
        answerB: matchup.answerB,
        voteResultA: percentA,
        voteResultB: percentB,
        pointsA: pointsA,
        pointsB: pointsB,
        quiplashA: totalVotes > 0 && votesA === totalVotes,
        quiplashB: totalVotes > 0 && votesB === totalVotes,
        matchupIndex: matchupIndex + 1,
        totalMatchups: matchups.length,
        scoreboardJson: JSON.stringify(scoreboard),
        timerRemaining: 0
      });

      await room.delay(REVEAL_DURATION_MS);
    }

    var roundScoreboard = party.createScoreboard(scores, playerNames);

    await room.updateSharedData({
      phase: "scores",
      roundNumber: round,
      roundMultiplier: round,
      scoreboardJson: JSON.stringify(roundScoreboard),
      timerRemaining: 0
    });

    await room.delay(SCORES_DURATION_MS);
  }

  var finalScoreboard = party.createScoreboard(scores, playerNames);
  var winner = finalScoreboard.length > 0 ? finalScoreboard[0] : null;

  await room.updateSharedData({
    phase: "winner",
    scoreboardJson: JSON.stringify(finalScoreboard),
    winnerName: winner ? winner.playerName : "Nobody",
    timerRemaining: 0
  });

  await room.delay(WINNER_DURATION_MS);
  await room.setPhase("ended");
};
